import os
from datetime import datetime, timezone

# Read the agent communications file
comm_file = "/home/bob/.hermes/.openclaw/memory/agent-communications.jsonl"
pending_tasks = []
if os.path.exists(comm_file):
    with open(comm_file, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
                # Consider tasks that are not completed or failed
                status = entry.get('status', '')
                if status not in ['completed', 'failed']:
                    pending_tasks.append(entry)
            except json.JSONDecodeError:
                pass

# Sort by timestamp if available
def get_ts(entry):
    ts = entry.get('timestamp')
    if ts:
        try:
            return datetime.fromisoformat(ts.replace('Z', '+00:00'))
        except:
            return datetime.min
    return datetime.min

pending_tasks.sort(key=get_ts, reverse=True)

print(f"Found {len(pending_tasks)} pending tasks in OpenClaw:")
for task in pending_tasks[:10]:  # Show up to 10
    print(f"- {task.get('task', 'No task description')} (ID: {task.get('task_id', 'unknown')})")
    print(f"  From: {task.get('from')} -> To: {task.get('to')}")
    print(f"  Status: {task.get('status')}")
    if task.get('timestamp'):
        print(f"  Timestamp: {task['timestamp']}")
    print()"}

