        print(f"   📄 Manuscript: {len(chapter_files)} chapter files")
        # Try to get chapter numbers
        chapters = []
        for f in chapter_files:
            # Extract chapter number if possible
            import re
            match = re.search(r'[_-]?(\d+)[_-]', f.name.upper())
            if match:
                chapters.append(int(match.group(1)))
            elif f.name.startswith('Chapter'):
                # Try to get number after Chapter
                parts = f.name.split()
                if len(parts) > 1:
                    try:
                        num = int(parts[1].rstrip(':_'))
                        chapters.append(num)
                    except:
                        pass
        if chapters:
            print(f"      Chapters: {min(chapters)}-{max(chapters)} (total {len(chapters)})")
    elif md_files:
        print(f"   📄 Manuscript: {len(md_files)} markdown files (non-chapter)")
    else:
        print(f"   📄 Manuscript: No markdown files found")

