        if output_epubs:
            print(f"      📤 Output EPUBs: {len(output_epubs)}")
    else:
        print(f"   📚 EPUB: No EPUB files found")

    # Check PDF status
    pdf_files = list(book_path.rglob("*.pdf"))
    if pdf_files:
        print(f"   📑 PDF: {len(pdf_files)} files")
        output_pdfs = [f for f in pdf_files if 'output' in str(f).lower()]
        if output_pdfs:
            print(f"      📤 Output PDFs: {len(output_pdfs)}")
    else:
        print(f"   📑 PDF: No PDF files found")

